package com.mengzhihua.crm.sales.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.Lead;import com.mengzhihua.crm.sales.service.LeadService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/leads") public class LeadController {private final LeadService s;public LeadController(LeadService x){s=x;}@GetMapping public Result<PageResult<Lead>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword){return Result.ok(s.list(page,size,keyword));}@GetMapping("/{id}")public Result<Lead> get(@PathVariable Long id){return Result.ok(s.get(id));}@PostMapping public Result<Lead> add(@RequestBody Lead x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<Lead> edit(@PathVariable Long id,@RequestBody Lead x){x.setId(id);return Result.ok(s.save(x));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}@PostMapping("/{id}/convert")public Result<Map<String,Long>> convert(@PathVariable Long id,@RequestBody Map<String,Object> b){return Result.ok(s.convert(id,b));}}
